import json

# In-memory storage
_todos = []
_next_id = 1

MAX_TITLE_LENGTH = 200


def _remaining():
    return sum(1 for t in _todos if not t["done"])


def _error(status, message):
    return status, {"error": message}


def _parse_body(body):
    if not body:
        return {}
    try:
        data = json.loads(body.decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        return None
    if not isinstance(data, dict):
        return None
    return data


def _find(todo_id):
    for t in _todos:
        if t["id"] == todo_id:
            return t
    return None


def _list_todos():
    return 200, {"items": [dict(t) for t in _todos], "remaining": _remaining()}


def _create_todo(body):
    global _next_id
    data = _parse_body(body)
    if data is None:
        return _error(400, "請求內容不是有效的 JSON")
    title = data.get("title")
    if not isinstance(title, str) or not title.strip():
        return _error(400, "標題不可為空")
    title = title.strip()
    if len(title) > MAX_TITLE_LENGTH:
        return _error(400, "標題過長（最多 %d 字）" % MAX_TITLE_LENGTH)
    todo = {"id": str(_next_id), "title": title, "done": False}
    _next_id += 1
    _todos.append(todo)
    return 201, dict(todo)


def _update_todo(todo_id, body):
    todo = _find(todo_id)
    if todo is None:
        return _error(404, "找不到指定的待辦")
    data = _parse_body(body)
    if data is None:
        return _error(400, "請求內容不是有效的 JSON")
    if "done" not in data or not isinstance(data["done"], bool):
        return _error(400, "done 必須為 true 或 false")
    todo["done"] = data["done"]
    return 200, dict(todo)


def _delete_todo(todo_id):
    todo = _find(todo_id)
    if todo is None:
        return _error(404, "找不到指定的待辦")
    _todos.remove(todo)
    return 200, {"deleted": True, "id": todo_id}


def _stats():
    return 200, {"remaining": _remaining(), "total": len(_todos)}


def handle(method, path, body):
    method = (method or "").upper()
    path = path or "/"
    if not path.startswith("/"):
        path = "/" + path
    if len(path) > 1:
        path = path.rstrip("/")

    if method == "OPTIONS":
        return 200, {}

    if path == "/todos":
        if method == "GET":
            return _list_todos()
        if method == "POST":
            return _create_todo(body)
        return _error(405, "不支援的請求方法")

    if path.startswith("/todos/"):
        todo_id = path[len("/todos/"):]
        if not todo_id or "/" in todo_id:
            return _error(404, "找不到路徑")
        if method == "PATCH":
            return _update_todo(todo_id, body)
        if method == "DELETE":
            return _delete_todo(todo_id)
        return _error(405, "不支援的請求方法")

    if path == "/stats":
        if method == "GET":
            return _stats()
        return _error(405, "不支援的請求方法")

    return _error(404, "找不到路徑")

