(function () {
  var form = document.getElementById('todo-form');
  var input = document.getElementById('todo-input');
  var list = document.getElementById('todo-list');
  var remainingEl = document.getElementById('remaining');
  var messageEl = document.getElementById('message');
  var emptyEl = document.getElementById('empty');

  function showMessage(text) {
    messageEl.textContent = text || '';
  }

  function request(method, path, payload) {
    var options = { method: method, headers: {} };
    if (payload !== undefined) {
      options.headers['Content-Type'] = 'application/json';
      options.body = JSON.stringify(payload);
    }
    return fetch('api/' + path, options).then(function (res) {
      return res.text().then(function (text) {
        var data = {};
        try {
          data = text ? JSON.parse(text) : {};
        } catch (e) {
          data = {};
        }
        if (!res.ok) {
          throw new Error(data.error || ('請求失敗（' + res.status + '）'));
        }
        return data;
      });
    });
  }

  function render(data) {
    var items = data.items || [];
    list.innerHTML = '';
    items.forEach(function (item) {
      var li = document.createElement('li');
      if (item.done) {
        li.className = 'done';
      }

      var checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = !!item.done;
      checkbox.setAttribute('aria-label', '標記完成：' + item.title);
      checkbox.addEventListener('change', function () {
        toggle(item.id, checkbox.checked);
      });

      var span = document.createElement('span');
      span.className = 'title';
      span.textContent = item.title;

      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'delete';
      del.textContent = '刪除';
      del.addEventListener('click', function () {
        remove(item.id);
      });

      li.appendChild(checkbox);
      li.appendChild(span);
      li.appendChild(del);
      list.appendChild(li);
    });
    emptyEl.hidden = items.length !== 0;
    remainingEl.textContent = String(data.remaining || 0);
  }

  function load() {
    return request('GET', 'todos').then(function (data) {
      showMessage('');
      render(data);
    }).catch(function (err) {
      showMessage(err.message);
    });
  }

  function toggle(id, done) {
    request('PATCH', 'todos/' + encodeURIComponent(id), { done: done })
      .then(load)
      .catch(function (err) {
        showMessage(err.message);
        load();
      });
  }

  function remove(id) {
    request('DELETE', 'todos/' + encodeURIComponent(id))
      .then(load)
      .catch(function (err) {
        showMessage(err.message);
        load();
      });
  }

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    var title = input.value.trim();
    if (!title) {
      showMessage('請輸入待辦事項標題');
      return;
    }
    request('POST', 'todos', { title: title })
      .then(function () {
        input.value = '';
        input.focus();
        return load();
      })
      .catch(function (err) {
        showMessage(err.message);
      });
  });

  load();
})();

